-- Supabase migration + seed data for the 'uganda_npms' pavement management raw survey tables.
-- This ports the repo's own local SQLite database (pms_backend.sqlite) schema+data as-is --
-- proper typed columns, not a generic jsonb blob, since the source was already relational.
-- Table names are prefixed npms_ to avoid collisions with uganda_ntis's existing tables.
-- NOTE: this does NOT yet sync pms_dashboard_data.json (the file the live site actually
-- reads) -- that file is a heavily pre-aggregated summary (region rollups, a PCI gauge,
-- a 150-segment sample, and trained ML metrics) and no script producing it from this raw
-- data exists anywhere in the repo's history, so reproducing it here would risk silently
-- wrong numbers on the live dashboard. Once the raw tables below are live in Supabase,
-- generating the dashboard rollups from them (in a sync job) can follow.

-- ── npms_pavement_visual_condition ──────────────────────
create table if not exists public.npms_pavement_visual_condition (
  id bigint primary key,
  link_id text,
  road_name text,
  station_region text,
  surface_type text,
  length_km double precision,
  pci_score double precision,
  vci_score double precision,
  iri_m_km double precision,
  cracking_pct double precision,
  rutting_mm double precision,
  potholes_per_km double precision,
  overall_rating text,
  survey_year bigint,
  data_source text
);
alter table public.npms_pavement_visual_condition enable row level security;
drop policy if exists "npms_pavement_visual_condition_public_read" on public.npms_pavement_visual_condition;
create policy "npms_pavement_visual_condition_public_read" on public.npms_pavement_visual_condition for select using (true);

-- ── npms_pavement_fwd_deflections ──────────────────────
create table if not exists public.npms_pavement_fwd_deflections (
  id bigint primary key,
  link_id text,
  section_no text,
  chainage_km double precision,
  stress_kpa double precision,
  load_kn double precision,
  d1_microns double precision,
  d2_microns double precision,
  d3_microns double precision,
  d4_microns double precision,
  d5_microns double precision,
  d6_microns double precision,
  d7_microns double precision,
  snc_modified_sn double precision
);
alter table public.npms_pavement_fwd_deflections enable row level security;
drop policy if exists "npms_pavement_fwd_deflections_public_read" on public.npms_pavement_fwd_deflections;
create policy "npms_pavement_fwd_deflections_public_read" on public.npms_pavement_fwd_deflections for select using (true);

-- ── npms_pavement_dcp_tests ──────────────────────
create table if not exists public.npms_pavement_dcp_tests (
