alter table public.npms_pavement_dcp_tests enable row level security;
drop policy if exists "npms_pavement_dcp_tests_public_read" on public.npms_pavement_dcp_tests;
create policy "npms_pavement_dcp_tests_public_read" on public.npms_pavement_dcp_tests for select using (true);

-- ── npms_traffic_axle_loads ──────────────────────
create table if not exists public.npms_traffic_axle_loads (
