alter table public.npms_traffic_axle_loads enable row level security;
drop policy if exists "npms_traffic_axle_loads_public_read" on public.npms_traffic_axle_loads;
create policy "npms_traffic_axle_loads_public_read" on public.npms_traffic_axle_loads for select using (true);

-- ── npms_manual_policy_formulas ──────────────────────
create table if not exists public.npms_manual_policy_formulas (
  id bigint primary key,
  manual_title text,
  formula_key text,
  formula_expression text,
  condition_rating_thresholds text,
  intervention_trigger_iri double precision,
