alter table public.npms_manual_policy_formulas enable row level security;
drop policy if exists "npms_manual_policy_formulas_public_read" on public.npms_manual_policy_formulas;
create policy "npms_manual_policy_formulas_public_read" on public.npms_manual_policy_formulas for select using (true);

