insert into public.npms_manual_policy_formulas (id, manual_title, formula_key, formula_expression, condition_rating_thresholds, intervention_trigger_iri, unit_cost_usd_per_km, derived_notes) values
(1, 'MoWT General Specifications for Road & Bridge Works', 'PAVED_PCI_FORMULA', 'PCI = 100 - (0.4 * Cracking% + 0.3 * Rutting_mm + 0.8 * Potholes/km)', 'PCI > 70: Good | 50-70: Fair | 30-50: Poor | < 30: Bad', 4.0, 150000.0, 'Derived from MoWT Pavement Rating Standards'),
(2, 'MoWT General Specifications for Road & Bridge Works', 'UNPAVED_VCI_FORMULA', 'VCI = 100 - (10 * Roughness_Score + 15 * Potholes_Score + 12 * Rutting_Score)', 'VCI > 70: Good | 50-70: Fair | 30-50: Poor | < 30: Bad', 6.5, 25000.0, 'Unpaved Gravel Loss & Regraveling Intervention Policy'),
(3, 'AASHTO Pavement Design Guide (1993)', 'STRUCTURAL_NUMBER_SNC', 'SNC = 0.0395 * D0^0.5 + 0.01 * (E1/E3)^0.33', 'SNC >= 4.5: Heavy Duty | 3.0-4.5: Medium | < 3.0: Overlay Required', 3.5, 320000.0, 'Structural Capacity Evaluation via FWD Deflections'),
(4, 'IMQS PMS Manual', 'IRI_INTERVENTION_TRIGGER', 'Intervention required when IRI > 4.2 m/km on Primary Paved Corridors', 'IRI <= 2.5: Excellent | 2.5-4.2: Acceptable | > 4.2: Resurfacing Trigger', 4.2, 85000.0, 'Routine & Periodic Maintenance Allocation Rules'),
(5, 'ROMDAS Pavement Evaluation Guidelines', 'ROUGHNESS_CALIBRATION', 'IRI_Calibrated = 0.85 * RAW_COUNT + 0.12', 'Calibrated IRI used for National Asset Valuations', 4.0, 45000.0, 'ROMDAS Bump Integrator Field Calibration Formula');
